import{_ as a,c as i,o as t,a2 as n}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse(`{"title":"Politique de confidentialité","description":"qDiff ne collecte pas vos données. Découvrez ce que l'application lit sur votre Mac et comment les achats sont traités.","frontmatter":{"title":"Politique de confidentialité","description":"qDiff ne collecte pas vos données. Découvrez ce que l'application lit sur votre Mac et comment les achats sont traités."},"headers":[],"relativePath":"fr/privacy/index.md","filePath":"fr/privacy/index.md","lastUpdated":1794296122000}`),s={name:"fr/privacy/index.md"};function o(r,e,c,l,u,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to &quot;Politique de confidentialité&quot;">​</a></h1><p><em>Dernière mise à jour : 6 novembre 2026</em></p><p><strong>En résumé : qDiff ne collecte aucune donnée personnelle.</strong> C&#39;est un outil local. Vos fichiers restent sur votre Mac.</p><h2 id="ce-que-lit-qdiff" tabindex="-1">Ce que lit qDiff <a class="header-anchor" href="#ce-que-lit-qdiff" aria-label="Permalink to &quot;Ce que lit qDiff&quot;">​</a></h2><p>qDiff ouvre uniquement les fichiers et les dossiers que vous choisissez dans l&#39;application, et les traite sur votre appareil pour afficher la comparaison. Si vous autorisez l&#39;accès à un dossier, cet accès est conservé pour votre confort et peut être retiré à tout moment dans les Réglages. Rien ne nous est envoyé.</p><h2 id="ce-que-nous-ne-faisons-pas" tabindex="-1">Ce que nous ne faisons pas <a class="header-anchor" href="#ce-que-nous-ne-faisons-pas" aria-label="Permalink to &quot;Ce que nous ne faisons pas&quot;">​</a></h2><ul><li>Nous ne collectons ni noms, ni adresses e-mail, ni statistiques d&#39;utilisation.</li><li>Nous ne vous suivons pas d&#39;une application ou d&#39;un site web à l&#39;autre.</li><li>Nous n&#39;exigeons ni compte ni connexion.</li><li>Nous n&#39;affichons aucune publicité et n&#39;incluons ni analytique ni suivi tiers.</li><li>Nous ne synchronisons ni ne sauvegardons vos fichiers sur aucun serveur.</li></ul><h2 id="acces-au-reseau" tabindex="-1">Accès au réseau <a class="header-anchor" href="#acces-au-reseau" aria-label="Permalink to &quot;Accès au réseau&quot;">​</a></h2><p>qDiff fonctionne hors ligne. La seule requête réseau facultative concerne la page « Plus d&#39;applications » intégrée à l&#39;application, qui charge une liste publique d&#39;applications. Cette requête ne contient aucune information sur vous, vos fichiers ou votre appareil, et aucune donnée d&#39;utilisation n&#39;est renvoyée.</p><h2 id="achats" tabindex="-1">Achats <a class="header-anchor" href="#achats" aria-label="Permalink to &quot;Achats&quot;">​</a></h2><p>L&#39;achat unique facultatif est entièrement géré par le Mac App Store et votre Apple ID. Nous ne voyons jamais vos informations de paiement. Vous pouvez restaurer un achat depuis les Réglages de l&#39;application.</p><h2 id="ce-site-web" tabindex="-1">Ce site web <a class="header-anchor" href="#ce-site-web" aria-label="Permalink to &quot;Ce site web&quot;">​</a></h2><p>Ce site est un ensemble de pages statiques. Il n&#39;y a ni connexion, ni analytique, ni cookies publicitaires. Ouvrir une page ne vous demande rien.</p><h2 id="enfants" tabindex="-1">Enfants <a class="header-anchor" href="#enfants" aria-label="Permalink to &quot;Enfants&quot;">​</a></h2><p>qDiff ne s&#39;adresse pas aux enfants et ne collecte sciemment aucune information sur qui que ce soit.</p><h2 id="modifications" tabindex="-1">Modifications <a class="header-anchor" href="#modifications" aria-label="Permalink to &quot;Modifications&quot;">​</a></h2><p>Si cette politique venait à changer, nous mettrions à jour cette page et la date ci-dessus. Toute modification affectant ce que l&#39;application lit sera également décrite dans l&#39;application elle-même.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Une question sur la confidentialité ? Écrivez à <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>.</p>',19)])])}const h=a(s,[["render",o]]);export{f as __pageData,h as default};
